#ifndef UI_FONT_HPP
#define UI_FONT_HPP

#include <cstdint>

namespace ui {

/**
 * @brief Monospaced bitmap font (generated by controller/ui/tools/gen_fonts.py).
 *
 * Each glyph is `height` rows of `bytes_per_row` bytes, MSB = leftmost pixel; the cell is
 * width x height with the baseline `ascent` rows below the top.
 */
struct Font {
    uint8_t width;
    uint8_t height;
    uint8_t ascent;
    uint8_t bytes_per_row;
    uint16_t count;
    uint16_t fallback;              // glyph index used for missing code points ('?')
    const uint16_t* codepoints;     // sorted
    const uint8_t* bitmap;

    /** @brief Glyph index of a code point (fallback if missing) */
    uint16_t index(uint32_t codepoint) const noexcept {
        uint16_t lo = 0;
        uint16_t hi = count;
        while (lo < hi) {
            const uint16_t mid = static_cast<uint16_t>((lo + hi) / 2);
            if (codepoints[mid] < codepoint) {
                lo = static_cast<uint16_t>(mid + 1);
            } else {
                hi = mid;
            }
        }
        return (lo < count && codepoints[lo] == codepoint) ? lo : fallback;
    }

    const uint8_t* glyph(uint16_t index) const noexcept {
        return bitmap + static_cast<uint32_t>(index) * height * bytes_per_row;
    }
};

extern const Font kFontSmall;   // 5x7  status bar, hints, small labels
extern const Font kFontBody;    // 6x10 menus and pages
extern const Font kFontBig;     // 10x20 large readouts

/**
 * @brief Decode one UTF-8 code point and advance `s`. Invalid bytes decode as U+FFFD.
 *        Returns 0 at the end of the string.
 */
uint32_t utf8_next(const char*& s) noexcept;

/** @brief Number of code points in a UTF-8 string */
int utf8_length(const char* s) noexcept;

} // namespace ui

#endif
